111	  const firstHeader = headerRows[0];
112	  if (!firstHeader) return false;
113	  const firstCellText = extractText((firstHeader.content ?? [])[0] ?? { nodeType: 'text', value: '' }).trim();
114	  // Grouped layout (Figma Layout 3) has a non-empty first header cell AND exactly one body row
115	  // per sub-table. Standard multi-row tables (e.g. Rings, Cuff Bracelets) have a non-empty
116	  // first header cell too — the body-row count is what distinguishes them.
117	  const bodyRowCount = rows.length - headerRows.length;
118	  return firstCellText !== '' && bodyRowCount === 1;
119	};
