121	/**
122	 * Renders a Figma "Layout 3" grouped size table.
123	 *
124	 * Each pair of consecutive rows (header + value) forms one group, rendered as an
125	 * independent semantic <table> so screen readers associate header cells with their data
126	 * cells. Columns share width equally via the browser's default table layout — each table
127	 * has a consistent column count within its rows, so no colspan arithmetic is needed even
128	 * though different groups have different counts (OSFA=1, S/M+M/L=2, S+M+L=3).
129	 *
130	 * When the rich text contains separate table nodes per group (the Contentful authoring
131	 * pattern), each call to GroupedSizeTable handles one table node (one group). The outer
132	 * renderRichText VStack provides spacing between tables in that case, and the inner VStack
133	 * here is a transparent no-op with a single child. When all groups are in one table node
134	 * (alternating header/value rows), the inner VStack provides the inter-group gap.
135	 */
136	const GroupedSizeTable = ({ node, unit }: { node: ContentfulRichTextNode; unit: Unit }) => {
137	  const allRows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
138	  const groups: ContentfulRichTextNode[][] = [];
139	  for (let i = 0; i < allRows.length; i += 2) groups.push(allRows.slice(i, i + 2));
140	
141	  return (
142	    <VStack align="stretch" spacing="var(--zimm-scale-xl)" width="100%">
143	      {groups.map((group, gi) => {
144	        const groupHeaderRows = group.filter(isHeaderRow);
145	        const groupBodyRows = group.filter((r) => !isHeaderRow(r));
146	        return (
147	          <chakra.table key={gi} width="100%" sx={{ borderCollapse: 'collapse', 'td, th': { whiteSpace: 'pre-line' } }}>
148	            {groupHeaderRows.length > 0 && (
149	              <chakra.thead>
150	                {groupHeaderRows.map((row, ri) => (
151	                  <chakra.tr key={ri}>
152	                    {(row.content ?? []).map((c, j) => (
153	                      <chakra.th
154	                        key={j}
155	                        textAlign="center"
156	                        textStyle="navigation"
157	                        color="var(--zimm-color-text-default)"
158	                        paddingX="var(--zimm-scale-2xs)"
159	                        paddingY="var(--zimm-scale-xl)"
160	                        borderBottom={BORDER_FOCUS}
161	                      >
162	                        {convertCellText(extractCellText(c), unit)}
163	                      </chakra.th>
164	                    ))}
165	                  </chakra.tr>
166	                ))}
167	              </chakra.thead>
168	            )}
169	            {groupBodyRows.length > 0 && (
170	              <chakra.tbody>
171	                {groupBodyRows.map((row, ri) => (
172	                  <chakra.tr key={ri}>
173	                    {(row.content ?? []).map((c, j) => (
174	                      <chakra.td
175	                        key={j}
176	                        textAlign="center"
177	                        textStyle="caption"
178	                        color="var(--zimm-color-text-default)"
179	                        paddingX="var(--zimm-scale-2xs)"
180	                        paddingY="var(--zimm-scale-xl)"
181	                        borderBottom={BORDER_SECONDARY}
182	                      >
183	                        {convertCellText(extractCellText(c), unit)}
184	                      </chakra.td>
185	                    ))}
186	                  </chakra.tr>
187	                ))}
188	              </chakra.tbody>
189	            )}
190	          </chakra.table>
191	        );
192	      })}
193	    </VStack>
194	  );
195	};
