346	/**
347	 * Renders a Rich Text document with section-aware spacing.
348	 *
349	 * Nodes are grouped into sections — each section ends when a `table` node is encountered.
350	 * Within a section (heading + description paragraphs + table), spacing is tight (`xl`).
351	 * Between sections the gap is wider (`4xl`) to visually separate table groups.
352	 *
353	 * Sections that contain no table and no non-empty text are dropped — this prevents
354	 * Contentful's auto-appended trailing empty paragraphs from creating phantom bottom space
355	 * via the VStack gap that would otherwise apply before an empty last section.
356	 */
357	const renderRichText = (doc: ContentfulRichText, unit: Unit): React.ReactNode => {
358	  const sections: ContentfulRichTextNode[][] = [];
359	  let current: ContentfulRichTextNode[] = [];
360	
361	  for (const node of doc.content) {
362	    current.push(node);
363	    if (node.nodeType === 'table') {
364	      sections.push(current);
365	      current = [];
366	    }
367	  }
368	  if (current.length > 0) sections.push(current);
369	
370	  const visibleSections = sections.filter((section) => {
371	    const hasTable = section.some((n) => n.nodeType === 'table');
372	    const hasText = section.some((n) => n.nodeType !== 'table' && extractText(n).trim() !== '');
